import requests, re, time
from bs4 import BeautifulSoup
from decimal import Decimal
BASE='https://www.worldometers.info'
html=requests.get(BASE+'/gdp/gdp-by-country/', timeout=30, headers={'User-Agent':'Mozilla/5.0'}).text
soup=BeautifulSoup(html,'html.parser')
tables=soup.find_all('table')
# map id -> href from first table
hrefs={}
for tr in tables[0].find_all('tr')[1:]:
    rid=tr.get('id')
    a=tr.find('a', href=True)
    if rid and a:
        hrefs[rid]=a['href']
# candidates from second table share >= 0.1
cands=[]
for tr in tables[1].find_all('tr')[1:]:
    tds=tr.find_all('td')
    if len(tds)<7: continue
    rank=tds[0].get_text(strip=True)
    if not rank.isdigit(): continue
    rid=tr.get('id')
    name=tds[1].get_text(' ', strip=True)
    share_txt=tds[6].get_text(strip=True).replace('%','').replace(',','')
    try:
        share=Decimal(share_txt)
    except Exception:
        continue
    if share >= Decimal('0.1'):
        cands.append((int(rank), rid, name, share_txt, hrefs.get(rid)))
print('candidates', len(cands))
print([c[2] for c in cands])

def parse_growth(txt):
    txt=txt.strip().replace('%','').replace(',','')
    txt=txt.replace('−','-').replace('–','-').replace('—','-')
    if txt in ('','-'):
        return None
    try:
        return float(txt)
    except Exception:
        return None

passing=[]; details=[]
for rank,rid,name,share,href in cands:
    if not href:
        href=f'/gdp/{rid}-gdp/'
    url=href if href.startswith('http') else BASE+href
    try:
        h=requests.get(url, timeout=20, headers={'User-Agent':'Mozilla/5.0'}).text
    except Exception as e:
        details.append((name,'FETCHERR',str(e),{},share,url)); continue
    sp=BeautifulSoup(h,'html.parser')
    vals={}
    for table in sp.find_all('table'):
        heads=[th.get_text(' ', strip=True) for th in table.find_all('th')]
        if 'Year' in heads and any('GDP Growth' in x for x in heads):
            growth_head=next(x for x in heads if 'GDP Growth' in x)
            gi=heads.index(growth_head)
            yi=heads.index('Year')
            for tr in table.find_all('tr')[1:]:
                cells=[td.get_text(' ', strip=True) for td in tr.find_all('td')]
                if len(cells)<=max(yi,gi): continue
                y=cells[yi].strip()
                if re.fullmatch(r'20(1[2-9]|20)', y):
                    vals[int(y)]=parse_growth(cells[gi])
            break
    needed=list(range(2012,2021))
    missing=[y for y in needed if y not in vals or vals[y] is None]
    ok=(not missing) and all(vals[y] > 1.5 for y in needed)
    details.append((name, ok, vals, missing, share, url))
    if ok:
        passing.append(name)
    time.sleep(0.05)
print('\nPASSING', len(passing))
print(passing)
print('\nDETAILS:')
for name, ok, vals, missing, share, url in details:
    if ok:
        print('OK', name, 'share', share, [vals[y] for y in range(2012,2021)])
    else:
        print('NO', name, 'share', share, 'missing', missing, 'vals', [vals.get(y) for y in range(2012,2021)], url)

import requests, json
url='https://api.worldbank.org/v2/country/all/indicator/NY.GDP.MKTP.KD.ZG?format=json&date=2012:2020&per_page=20000'
data=requests.get(url, timeout=60).json()[1]
by={}
for row in data:
    name=row['country']['value']; iso=row.get('countryiso3code') or ''
    year=int(row['date']); val=row['value']
    by.setdefault((name,iso), {})[year]=val
res=[]
for (name,iso), vals in by.items():
    if all(y in vals and vals[y] is not None for y in range(2012,2021)):
        if all(vals[y] > 1.5 for y in range(2012,2021)):
            res.append((name,iso,[round(vals[y],3) for y in range(2012,2021)]))
print('count', len(res))
for name,iso,vals in sorted(res):
    print(name, iso, vals)
